import json
import os
import re

def task_func(
    file_path,
    attribute,
    INPUT_JSON={
        "type": "object",
        "properties": {
            "name": {"type": str},  
            "age": {"type": int},   
            "email": {"type": str}  
        },
        "required": ["name", "age", "email"]
    },
    EMAIL_REGEX=r"^[a-z0-9]+[\._]?[a-z0-9]+[@]\w+[.]\w{2,3}$"):

    if not os.path.exists(file_path):
        raise ValueError("File does not exist")

    with open(file_path, 'r') as f:
        data = json.load(f)

    for req in INPUT_JSON["required"]:
        if req not in data:
            raise ValueError(f"Missing required attribute: {req}")

    for key, schema in INPUT_JSON["properties"].items():
        if key in data:
            if not isinstance(data[key], schema["type"]):
                raise ValueError(f"Type mismatch for {key}")

    if not re.match(EMAIL_REGEX, data.get("email", "")):
        raise ValueError("Invalid email format")

    if attribute not in data:
        raise ValueError(f"Attribute {attribute} not found in JSON")

    return data[attribute]
```

