    for req in INPUT_JSON["required"]:
        if req not in data:
            raise ValueError(f"Missing required attribute: {req}")

    for key, schema in INPUT_JSON["properties"].items():
        if key in data:
            if not isinstance(data[key], schema["type"]):
                raise ValueError(f"Type mismatch for {key}")

    if not re.match(EMAIL_REGEX, data.get("email", "")):
